/**
 * Expand the repo-owned W2B worklist response into n8n items.
 * Tolerates wrapped HTTP-response shapes from n8n and falls back to the
 * original webhook payload for skipped-path identity fields.
 */
function asObject(value) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}

function firstNonEmpty(...values) {
  for (const value of values) {
    if (typeof value === 'string') {
      const trimmed = value.trim();
      if (trimmed && trimmed !== 'undefined' && trimmed !== 'null') {
        return trimmed;
      }
      continue;
    }

    if (value !== undefined && value !== null) {
      return value;
    }
  }

  return null;
}

function unwrapResponse(value) {
  const obj = asObject(value);
  if (Array.isArray(obj.workItems) || obj.summary || obj.orderId || obj.characterHash) {
    return obj;
  }

  for (const candidate of [obj.body, obj.data, obj.response, obj.result]) {
    const nested = asObject(candidate);
    if (Array.isArray(nested.workItems) || nested.summary || nested.orderId || nested.characterHash) {
      return nested;
    }
  }

  return obj;
}

function getWebhookPayload() {
  try {
    const webhook = $items('Webhook Trigger', 0, $runIndex)?.[0]?.json || {};
    return asObject(webhook.body && webhook.body !== webhook ? webhook.body : webhook);
  } catch {
    return {};
  }
}

const current = unwrapResponse($json || {});
let upstream = {};
try {
  upstream = unwrapResponse($items('Normalize 2B Input', 0, $runIndex)?.[0]?.json || {});
} catch {}

const webhookPayload = getWebhookPayload();
const response = Object.keys(upstream).length ? upstream : current;
const summary = asObject(response.summary);
const workItems = Array.isArray(response.workItems) ? response.workItems : [];
const orderId = firstNonEmpty(
  response.orderId,
  current.orderId,
  webhookPayload.orderId,
  webhookPayload.order_id,
  null,
);
const rootOrderId = firstNonEmpty(
  response.rootOrderId,
  response.amazonOrderId,
  current.rootOrderId,
  current.amazonOrderId,
  webhookPayload.rootOrderId,
  webhookPayload.root_order_id,
  webhookPayload.amazonOrderId,
  webhookPayload.amazon_order_id,
  null,
);
const amazonOrderId = firstNonEmpty(
  response.amazonOrderId,
  response.rootOrderId,
  current.amazonOrderId,
  current.rootOrderId,
  webhookPayload.amazonOrderId,
  webhookPayload.amazon_order_id,
  webhookPayload.rootOrderId,
  webhookPayload.root_order_id,
  null,
);
const characterHash = firstNonEmpty(
  response.characterHash,
  current.characterHash,
  webhookPayload.characterHash,
  webhookPayload.character_hash,
  null,
);
const backendUrl = firstNonEmpty(
  response.backendUrl,
  current.backendUrl,
  webhookPayload.backendUrl,
  'https://admin.littleherolabs.com',
);
const callbackUrl = firstNonEmpty(response.callbackUrl, current.callbackUrl, webhookPayload.callbackUrl, null);
const manifest2bKey = firstNonEmpty(response.manifest2bKey, current.manifest2bKey, null);

if (!workItems.length) {
  return [{
    json: {
      orderId,
      rootOrderId,
      amazonOrderId,
      characterHash,
      backendUrl,
      callbackUrl,
      manifest2bKey,
      scheduled: Number(summary.scheduled || 0),
      reason: summary.reason || 'NO_APPROVED_POSES',
      totalApproved: Number(summary.totalApproved || 0),
      skippedByBriaStatus: Number(summary.skippedByBriaStatus || 0),
      skippedBy2BManifest: Number(summary.skippedBy2BManifest || 0),
      skippedTotal: Number(summary.skippedTotal || 0),
    },
  }];
}

const scheduled = workItems.length;
return workItems.map((item) => ({
  json: {
    backendUrl,
    callbackUrl,
    manifest2bKey,
    ...item,
    scheduled,
  },
}));

/**
 * Final response payload (does not wait for workers).
 * Tolerates wrapped HTTP-response shapes from n8n and falls back to the
 * original webhook payload for identity fields.
 */
function asObject(value) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}

function firstNonEmpty(...values) {
  for (const value of values) {
    if (typeof value === 'string') {
      const trimmed = value.trim();
      if (trimmed && trimmed !== 'undefined' && trimmed !== 'null') {
        return trimmed;
      }
      continue;
    }

    if (value !== undefined && value !== null) {
      return value;
    }
  }

  return null;
}

function unwrapResponse(value) {
  const obj = asObject(value);
  if (Array.isArray(obj.workItems) || obj.summary || obj.orderId || obj.characterHash) {
    return obj;
  }

  for (const candidate of [obj.body, obj.data, obj.response, obj.result]) {
    const nested = asObject(candidate);
    if (Array.isArray(nested.workItems) || nested.summary || nested.orderId || nested.characterHash) {
      return nested;
    }
  }

  return obj;
}

function getWebhookPayload() {
  try {
    const webhook = $items('Webhook Trigger', 0, $runIndex)?.[0]?.json || {};
    return asObject(webhook.body && webhook.body !== webhook ? webhook.body : webhook);
  } catch {
    return {};
  }
}

let ctx = {};
try { ctx = unwrapResponse($items('Normalize 2B Input', 0, $runIndex)?.[0]?.json || {}); } catch {}
const webhookPayload = getWebhookPayload();
const summary = asObject(ctx.summary);
return [{ json: {
  orderId: firstNonEmpty(ctx.orderId, webhookPayload.orderId, webhookPayload.order_id, null),
  rootOrderId: firstNonEmpty(ctx.rootOrderId, ctx.amazonOrderId, webhookPayload.rootOrderId, webhookPayload.root_order_id, webhookPayload.amazonOrderId, webhookPayload.amazon_order_id, null),
  amazonOrderId: firstNonEmpty(ctx.amazonOrderId, ctx.rootOrderId, webhookPayload.amazonOrderId, webhookPayload.amazon_order_id, webhookPayload.rootOrderId, webhookPayload.root_order_id, null),
  scheduled: Number(summary.scheduled || 0),
  callbackUrl: firstNonEmpty(ctx.callbackUrl, webhookPayload.callbackUrl, null),
  batchSize: ctx.batchSize || 1,
  backendUrl: firstNonEmpty(ctx.backendUrl, webhookPayload.backendUrl, 'https://admin.littleherolabs.com'),
  manifest2bKey: firstNonEmpty(ctx.manifest2bKey, null),
  characterHash: firstNonEmpty(ctx.characterHash, webhookPayload.characterHash, webhookPayload.character_hash, null),
} }];

/**
 * Normalize Result - Extract and normalize sub-workflow output for aggregator.
 * Uses repo-provided manifest keys/URLs from the W2B worklist route.
 */
const j = $json || {};
const pick = (...v) => v.find(x => x !== undefined && x !== null && x !== '');
let result = j.result || j;

let ctx = {};
try { ctx = $items('Normalize 2B Input', 0, $runIndex)?.[0]?.json || {}; } catch {}

const orderId = pick(result.orderId, j.orderId, ctx.orderId, null);
const amazonOrderId = pick(result.amazonOrderId, j.amazonOrderId, ctx.amazonOrderId, null);
const characterHash = pick(result.characterHash, j.characterHash, ctx.characterHash, null);
const poseNumberRaw = pick(result.poseNumber, j.poseNumber, null);
const poseNumber = (poseNumberRaw === 0 || poseNumberRaw === '0') ? 0 : Number(poseNumberRaw);

if (!orderId) throw new Error('2B aggregator: orderId required');
if (!characterHash) throw new Error('2B aggregator: characterHash required');
if (!Number.isFinite(poseNumber)) throw new Error('2B aggregator: poseNumber required');

const backendUrl = pick(result.backendUrl, j.backendUrl, ctx.backendUrl, 'https://admin.littleherolabs.com');
const manifest2aUrl = pick(result.manifest2aUrl, j.manifest2aUrl, ctx.manifest2aUrl, null);
const manifest2bKey = pick(result.manifest2bKey, j.manifest2bKey, ctx.manifest2bKey, null);
const orderPrefix = pick(result.orderPrefix, j.orderPrefix, ctx.orderPrefix, null);

if (!manifest2aUrl) throw new Error('2B aggregator: manifest2aUrl required');
if (!manifest2bKey) throw new Error('2B aggregator: manifest2bKey required');

const normalizedResult = {
  orderId,
  amazonOrderId,
  characterHash,
  poseNumber,
  manifest2aUrl,
  manifest2bKey,
  orderPrefix,
  approvedKey: pick(result.approvedKey, null),
  sourceReplacedAt: pick(result.sourceReplacedAt, null),
  sourceReplacementCount: Number(pick(result.sourceReplacementCount, 0) || 0),
  sourceUrl: pick(result.sourceUrl, null),
  briaStatus: pick(result.briaStatus, 'error'),
  briaRequestId: pick(result.briaRequestId, null),
  briaStatusUrl: pick(result.briaStatusUrl, null),
  briaCompletedAt: pick(result.briaCompletedAt, null),
  briaErrorMessage: pick(result.briaErrorMessage, null),
  bgRemovedKey: pick(result.bgRemovedKey, null),
  bgRemovedContentType: pick(result.bgRemovedContentType, null),
  bgRemovedSizeBytes: (result.bgRemovedSizeBytes === 0 ? 0 : (Number(result.bgRemovedSizeBytes) || null)),
  bgRemovedImageUrl: pick(result.bgRemovedImageUrl, null),
  qa: (result.qa && typeof result.qa === 'object') ? result.qa : null,
  needsReview: !!pick(result.needsReview, false),
  reviewReason: pick(result.reviewReason, null),
};

return [{ json: { backendUrl, manifest2aUrl, manifest2bKey, orderPrefix, amazonOrderId, result: normalizedResult } }];

/**
 * Merge the incoming pose result into 2B manifest (create if missing).
 * Uses repo-provided manifest keys/URLs before any fallback logic.
 */
let ctx = {};
try { ctx = $items('Normalize Result', 0, $runIndex)?.[0]?.json || {}; } catch {}
const incoming = ctx.result || {};

const orderId = incoming.orderId || ctx.orderId || null;
if (!orderId) throw new Error('2B aggregator: missing orderId in Normalize Result');

const backendUrl = ctx.backendUrl || incoming.backendUrl || 'https://admin.littleherolabs.com';
const manifest2bMaybe = $items('Download 2B Manifest (if exists)', 0, $runIndex)?.[0]?.json || null;
const manifest2aHint = incoming.manifest2aUrl || ctx.manifest2aUrl || null;

function asManifest(raw) {
  if (!raw) return null;
  if (raw.schema) return raw;
  const text = typeof raw === 'string' ? raw : (raw.data || raw.body || null);
  if (!text || typeof text !== 'string') return null;
  try {
    const parsed = JSON.parse(text);
    return parsed && parsed.schema ? parsed : null;
  } catch {
    return null;
  }
}

let manifest2a = null;
try {
  manifest2a = asManifest($items('Download 2A Manifest (for merge)', 0, $runIndex)?.[0]?.json);
} catch {}

if (!manifest2a && manifest2aHint) {
  try {
    const http = this.helpers.httpRequest;
    const url = String(manifest2aHint) + (String(manifest2aHint).includes('?') ? '&' : '?') + 'v=' + Date.now();
    const raw = await http({ method: 'GET', url, json: false, timeout: 90000 });
    manifest2a = asManifest(raw);
  } catch {}
}

if (!incoming || !incoming.characterHash || !Number.isFinite(Number(incoming.poseNumber))) {
  throw new Error('2B aggregator: invalid Normalize Result payload');
}

if (!manifest2a || !manifest2a.schema) {
  throw new Error('2B aggregator: missing 2A manifest or invalid schema (orderId=' + orderId + ', manifest2aUrl=' + manifest2aHint + ')');
}

let manifest2b = (manifest2bMaybe && manifest2bMaybe.schema === 'lhb.run-manifest@v2.0') ? manifest2bMaybe : null;
if (!manifest2b) {
  manifest2b = JSON.parse(JSON.stringify(manifest2a));
  manifest2b.stage = '2b';
  manifest2b.createdAt = new Date().toISOString();
  manifest2b.updatedAt = new Date().toISOString();
  (manifest2b.entries || []).forEach(e => {
    e.bgRemovedKey = null;
    e.bgRemovedImageUrl = null;
    e.briaStatus = null;
    e.briaRequestId = null;
    e.briaStatusUrl = null;
    e.briaErrorMessage = null;
    e.sourceApprovedKey = null;
    e.sourceReplacedAt = null;
    e.sourceReplacementCount = 0;
    e.processedAt = null;
    e.needsReview = false;
    e.reviewReason = null;
    e.isFlagged = false;
  });
}

const poseNumber = Number(incoming.poseNumber);
const entry = (manifest2b.entries || []).find(e => Number(e.poseNumber) === poseNumber);
if (!entry) throw new Error('2B aggregator: pose ' + poseNumber + ' not found in manifest entries');

entry.sourceApprovedKey = incoming.approvedKey || entry.approvedKey || null;
entry.sourceReplacedAt = incoming.sourceReplacedAt || null;
entry.sourceReplacementCount = Number(incoming.sourceReplacementCount || 0);
entry.processedAt = new Date().toISOString();
entry.briaStatus = incoming.briaStatus;
entry.briaRequestId = incoming.briaRequestId || null;
entry.briaStatusUrl = incoming.briaStatusUrl || null;
entry.briaErrorMessage = incoming.briaErrorMessage || null;
if (incoming.qa && typeof incoming.qa === 'object') {
  entry.qa = { ...(entry.qa || {}), ...incoming.qa };
}

if (incoming.briaStatus === 'completed') {
  entry.bgRemovedKey = incoming.bgRemovedKey || entry.bgRemovedKey;
  entry.bgRemovedImageUrl = incoming.bgRemovedImageUrl || entry.bgRemovedImageUrl;
  entry.bgRemovedStatus = 'completed';
  entry.bgRemoved = true;
  entry.needsReview = incoming.needsReview === true;
  entry.reviewReason = incoming.needsReview === true ? (incoming.reviewReason || 'transparency_fail_or_low_conf') : null;
  if (incoming.needsReview !== true) entry.isFlagged = false;
} else {
  entry.bgRemoved = false;
  entry.bgRemovedStatus = incoming.briaStatus;
  entry.needsReview = true;
  entry.reviewReason = incoming.reviewReason || 'unknown';
}

manifest2b.updatedAt = new Date().toISOString();
const approved2a = (manifest2a.entries || []).filter(e => e && e.approved && e.status === 'approved');
const approvedCount = approved2a.length;
const isTerminal = (s) => ['completed','failed','timeout','error'].includes(String(s||'').toLowerCase());
const approvedNums = new Set(approved2a.map(e => Number(e.poseNumber)));
const terminalApproved = (manifest2b.entries || []).filter(e => approvedNums.has(Number(e.poseNumber)) && isTerminal(e.briaStatus)).length;
const complete = (approvedCount > 0) && (terminalApproved === approvedCount);
const approvedEntries2b = (manifest2b.entries || []).filter(e => approvedNums.has(Number(e.poseNumber)));
const needsHumanReview = approvedEntries2b.some(e => e.needsReview === true || e.needs_review === true);
const allSucceeded = approvedEntries2b.every(e => String(e.briaStatus||'').toLowerCase() === 'completed');
const readyForBook = allSucceeded && !needsHumanReview;
manifest2b.summary = manifest2b.summary || {};
manifest2b.summary.approvedPoseCount = approvedCount;
manifest2b.summary.terminalPoseCount = terminalApproved;
manifest2b.summary.complete = complete;
manifest2b.summary.needsHumanReview = needsHumanReview;
manifest2b.summary.readyForBook = readyForBook;

return [{ json: { manifest2b, complete, manifest2bKey: ctx.manifest2bKey, backendUrl: ctx.backendUrl || backendUrl, orderId: incoming.orderId, amazonOrderId: incoming.amazonOrderId || ctx.amazonOrderId || null, characterHash: incoming.characterHash } }];

/**
 * Create binary for S3 upload (manifest JSON).
 */
const manifest = $json.manifest2b;
const s = JSON.stringify(manifest, null, 2);
const b64 = Buffer.from(s, 'utf8').toString('base64');

return [{
  json: { manifest2bKey: $json.manifest2bKey, complete: $json.complete, backendUrl: $json.backendUrl, orderId: $json.orderId, amazonOrderId: $json.amazonOrderId || null, characterHash: $json.characterHash, needsHumanReview: $json.manifest2b?.summary?.needsHumanReview || false },
  binary: {
    data: {
      data: b64,
      mimeType: 'application/json',
      fileName: '2b-manifest.json'
    }
  }
}];

